function toast(msg,type='ok'){let t=$('#ip35Toast');if(!t){t=document.createElement('div');t.id='ip35Toast';document.body.appendChild(t)}t.className='ip35-toast '+type;t.textContent=msg;requestAnimationFrame(()=>t.classList.add('show'));clearTimeout(t._tm);t._tm=setTimeout(()=>t.classList.remove('show'),2600)}
function beep(kind='tap'){if(!state.sound)return;try{const C=window.AudioContext||window.webkitAudioContext;if(!C)return;const c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=kind==='error'?220:kind==='success'?740:520;o.type=kind==='error'?'sawtooth':'sine';g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(.035,c.currentTime+.01);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+.08);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.1)}catch{}}
async function getCsrf(force=false){if(state.csrf&&!force)return state.csrf;const r=await fetch(API+'/auth/csrf',{credentials:'include',cache:'no-store',headers:{Accept:'application/json'}});const d=await r.json().catch(()=>({}));if(!r.ok||!d.csrf)throw new Error('دریافت CSRF از Backend ناموفق بود.');state.csrf=d.csrf;return state.csrf}
async function req(path,opt={},retry=true){let token='';if(!/^(GET|HEAD)$/i.test(opt.method||'GET')){try{token=await getCsrf()}catch{}}
 const headers={'Accept':'application/json',...(opt.body instanceof FormData?{}:{'Content-Type':'application/json'}),...(opt.headers||{})};if(token)headers['X-CSRF-Token']=token;
 const r=await fetch(API+'/'+String(path).replace(/^\/+/,''),{credentials:'include',cache:'no-store',...opt,headers});const d=await r.json().catch(()=>({}));
 if(r.status===419&&retry){state.csrf=null;return req(path,opt,false)}
 if(!r.ok||d.ok===false)throw Object.assign(new Error(d.message||`HTTP ${r.status}`),{status:r.status,data:d});return d;
}
function showLogin(){state.demo=false;const l=$('#login'),d=$('#dashboard');if(!l||!d)return;l.style.display='grid';l.setAttribute('aria-hidden','false');d.style.display='none';d.classList.remove('active');document.body.classList.remove('ip35-auth');}
function showDash(name='پیج کسب‌وکار من',handle='@demo.page',isDemo=false){state.demo=!!isDemo;const l=$('#login'),d=$('#dashboard');if(!d)return;$('#name').textContent=name;$('#handle').textContent=handle;$('#avatar').textContent=(name||'م').trim().charAt(0)||'م';$('#profileName')&&($('#profileName').textContent=name);$('#profileHandle')&&($('#profileHandle').textContent=handle);$('#profileInitial')&&($('#profileInitial').textContent=(name||'م').trim().charAt(0)||'م');l.style.display='none';l.setAttribute('aria-hidden','true');d.style.display='block';d.classList.add('active','ip35-dashboard');document.body.classList.add('ip35-auth');go('home');}
