function setupLogin(){const form=$('#loginBtn');if(form){form.onclick=async()=>{const u=$('#user').value.trim(),p=$('#pass').value,err=$('#err');if(!u||!p){err.textContent='لطفاً نام کاربری و رمز عبور را وارد کنید.';err.classList.add('show');beep('error');return}err.classList.remove('show');const old=form.innerHTML;form.disabled=true;form.innerHTML='در حال ورود امن…';try{const d=await req('/auth/login',{method:'POST',body:JSON.stringify({username:u,password:p})});if(d.csrf)state.csrf=d.csrf;showDash(d.user?.display_name||u,'@'+(d.user?.username||u));await loadNotifications();toast('✓ ورود موفق بود');beep('success')}catch(e){err.textContent=e.message||'ورود انجام نشد.';err.classList.add('show');beep('error')}finally{form.disabled=false;form.innerHTML=old}}}
 $('#demoBtn')?.addEventListener('click',()=>{state.demo=true;state.security.authenticated=false;clearInterval(state.security.pollTimer);showDash('پیج کسب‌وکار من','@demo.page',true);updateBellBadge(0);toast('✓ حالت Demo واقعی فعال شد — همه ابزارهای نمایشی آماده‌اند');beep('success')});
 ['#user','#pass'].forEach(s=>$(s)?.addEventListener('keydown',e=>{if(e.key==='Enter')form?.click()}));
}
