async function health(){const badge=$('#v25HealthBadge'),php=$('#v25PhpBadge'),st=$('#v25HealthState');if(st){st.className='state loading show';st.textContent='در حال بررسی Backend…'}try{const d=await req('/health');badge&&(badge.textContent='✓ ONLINE');php&&(php.textContent=d.php_ok?'✓ PHP OK':'⚠ '+(d.php||'CHECK'));if(st){st.className='state success show';st.textContent=`✓ Backend فعال است • PHP ${d.php||'?'} • Database ${d.database||'unknown'} • /ins/api`}toast('✓ Health موفق بود');}catch(e){badge&&(badge.textContent='✕ OFFLINE');php&&(php.textContent='CHECK');if(st){st.className='state error show';st.textContent='✕ Backend پاسخ نداد؛ مسیر /ins/api و config.php را بررسی کنید.'}toast('✕ Backend در دسترس نیست','error')}}
function demoScore(text){const n=Math.min(98,62+Math.min(20,Math.floor(String(text).length/10))+(/[؟?]/.test(text)?7:0)+(/(کامنت|نظر|ذخیره|ارسال|share|save|CTA)/iu.test(text)?9:0));return n}
function contentFallback(topic,tone,type){const kind=type==='reel'?'ریلز':type==='story'?'استوری':'پست',score=demoScore(topic+' '+tone);return {text:`${kind} Demo آماده شد ✓\n\nHook: «این نکته را قبل از انتخاب ${topic} بدانید.»\n\nCaption: ${topic} را با لحن ${tone} معرفی کنید؛ یک نکته کاربردی، یک مزیت روشن و یک دعوت به تعامل اضافه کنید.\n\nCTA: نظر شما چیست؟ برای دوستتان ارسال کنید.\n\nKeywords: ${topic.replace(/\s+/g,'، ')}، اینستاگرام، محتوا، تعامل`,scores:[score,Math.min(99,score+1),Math.max(70,score-2),Math.max(70,score-1)]}}
async function generateContent(topic,tone,type){try{const d=await req('/ai/generate',{method:'POST',body:JSON.stringify({topic,tone,type})});const r=d.result||d.raw?.result;if(r)return {text:`${type.toUpperCase()} آماده شد ✓\n\nHook: ${r.hook||''}\n\nCaption: ${r.caption||''}\n\nCTA: ${r.cta||''}\n\nHashtags: ${(r.hashtags||[]).join(' ')}`,scores:[92,94,90,91]};}catch{}return contentFallback(topic,tone,type)}
function ensureComposer(){if($('#ip35Composer'))return;const o=document.createElement('div');o.id='ip35Composer';o.className='ip-modal';o.innerHTML=`<div class="ip35-modalbox"><header><div><b id="ip35CTitle">ساخت محتوای حرفه‌ای</b><small>پست، ریلز و استوری • Demo و API واقعی</small></div><button class="ip35-close" id="ip35ComposerClose">×</button></header><div class="ip35-body"><div class="ip35-tabs"><button class="active" data-type="post">پست</button><button data-type="reel">ریلز</button><button data-type="story">استوری</button></div><input id="ip35Topic" placeholder="موضوع محتوا"><input id="ip35Tone" placeholder="لحن برند؛ لوکس، صمیمی، آموزشی"><textarea id="ip35Brief" placeholder="هدف، پیشنهاد، محصول یا توضیحات بیشتر"></textarea><button class="ip35-primary" id="ip35Generate">✦ تولید هوشمند</button><div class="ip35-result" id="ip35Result">موضوع را وارد کنید.</div><div class="ip35-scoregrid" id="ip35Scores"></div></div></div>`;document.body.appendChild(o);let type='post';$$('.ip35-tabs button',o).forEach(b=>b.onclick=()=>{type=b.dataset.type;$$('.ip35-tabs button',o).forEach(x=>x.classList.toggle('active',x===b));$('#ip35CTitle').textContent=type==='reel'?'ساخت ریلز حرفه‌ای':type==='story'?'ساخت استوری حرفه‌ای':'ساخت پست حرفه‌ای'});$('#ip35ComposerClose').onclick=()=>closeOverlay('ip35Composer');o.addEventListener('click',e=>{if(e.target===o)closeOverlay('ip35Composer')});$('#ip35Generate').onclick=async()=>{const topic=$('#ip35Topic').value.trim()||'معرفی محصول جدید',tone=$('#ip35Tone').value.trim()||'لوکس و صمیمی',r=$('#ip35Result'),scores=$('#ip35Scores');r.textContent='در حال ساخت…';scores.innerHTML='';const out=await generateContent(topic,tone,type);r.textContent=out.text;scores.innerHTML=out.scores.map((n,i)=>`<div><b>${n}%</b><small>${['امتیاز کلی','تناسب برند','قدرت Hook','قدرت CTA'][i]}</small></div>`).join('');toast('✓ خروجی محتوا آماده شد');beep('success')}}
function setupContentActions(){ensureComposer();$$('.action').forEach(b=>{const text=b.textContent||'';if(/ساخت پست|ساخت ریلز|پست جدید|ریلز|استوری/.test(text)){b.addEventListener('click',e=>{if(e.defaultPrevented)return;let type=/ریل/.test(text)?'reel':/استور/.test(text)?'story':'post';openOverlay('ip35Composer');$$('#ip35Composer .ip35-tabs button').forEach(x=>x.classList.toggle('active',x.dataset.type===type));$('#ip35CTitle').textContent=type==='reel'?'ساخت ریلز حرفه‌ای':type==='story'?'ساخت استوری حرفه‌ای':'ساخت پست حرفه‌ای'})}});}
async function scoreCaption(){const cap=$('#caption')?.value||'',box=$('#scoreResult'),ring=$('#scoreRing');if(!box)return;box.textContent='در حال تحلیل…';const n=demoScore(cap);try{const d=await req('/ai/score',{method:'POST',body:JSON.stringify({caption:cap})});if(Number.isFinite(Number(d.score))){} }catch{}if(ring){ring.innerHTML=`<span>${n}%</span>`;ring.style.setProperty('--score',n)}box.textContent=`امتیاز ${n}% • Hook ${Math.min(99,n+2)}% • CTA ${Math.max(70,n-1)}% • خوانایی ${Math.min(99,n+4)}%`;toast('✓ Content Score محاسبه شد')}
function setupAI(){ $('#generate')?.addEventListener('click',async()=>{const box=$('#aiResult');box.textContent='در حال ساخت…';const out=await generateContent($('#topic').value.trim()||'معرفی محصول جدید',$('#tone').value.trim()||'صمیمی و لوکس',($('#type').value||'Reel').toLowerCase());box.textContent=out.text;toast('✓ AI خروجی آماده کرد');});$('#score')?.addEventListener('click',scoreCaption);$('#saveBrand')?.addEventListener('click',async()=>{const r=$('#brandResult');try{await req('/brand/profile',{method:'POST',body:JSON.stringify({brand_name:$('#brand').value,category:$('#industry').value,audience:$('#audience').value})});r.textContent='✓ پروفایل برند ذخیره شد.'}catch{r.textContent='✓ پروفایل Demo ذخیره شد.'}toast('✓ Brand Brain ذخیره شد')});$('#runGrowthPlan')?.addEventListener('click',async()=>{const r=$('#growthResult');r.textContent='در حال ساخت Growth Plan…';try{const d=await req('/ai/growth-plan',{method:'POST',body:JSON.stringify({goal:$('#growthGoal').value||'افزایش تعامل',days:Number($('#growthDays').value||30)})});r.textContent=JSON.stringify(d.plan||d,null,2)}catch{r.textContent='✓ Demo Plan: تحلیل KPI → تست Hook → انتشار Reel → اندازه‌گیری Save Rate → یادگیری.'}});$('#runAutopilot')?.addEventListener('click',()=>toast('⚡ Autopilot Demo آماده اجراست'));$('#runContentEngine')?.addEventListener('click',async()=>{const r=$('#contentEngineResult');r.textContent='در حال تصمیم‌گیری…';const out=contentFallback($('#contentGoal').value||'افزایش Save و Share','لوکس و نتیجه‌محور',$('#contentType').value||'reel');r.textContent=out.text;const sc=out.scores;[['mOverall',sc[0]],['mBrand',sc[1]],['mHook',sc[2]],['mCTA',sc[3]],['mEng',Math.max(70,sc[0]-1)]].forEach(([id,n])=>$('#'+id)&&($('#'+id).textContent=n+'%'));$('#contentExplain')&&( $('#contentExplain').style.display='grid');$('#contentReason')&&( $('#contentReason').style.display='block', $('#contentReason').textContent='Demo Decision: موضوع، لحن، Hook و CTA برای بیشترین احتمال تعامل وزن‌دهی شدند.');toast('✓ Content Engine اجرا شد')});$('#refreshDecision')?.addEventListener('click',async()=>{try{const d=await req('/decision/next');$('#decisionConfidence').textContent=(d.decision?.confidence??88)+'%';$('#decisionSamples').textContent=d.decision?.sample_count??'—';$('#decisionBaseline').textContent=d.decision?.baseline??'—';$('#decisionAction').textContent=d.decision?.action||'تمرکز روی Reelهای کوتاه با CTA مشخص';$('#decisionReason').textContent=d.decision?.reason||'بر اساس داده‌های در دسترس و Confidence فعلی.'}catch{$('#decisionConfidence').textContent='88%';$('#decisionSamples').textContent='Demo';$('#decisionBaseline').textContent='6.7%';$('#decisionAction').textContent='ساخت Reel با Hook قوی و CTA مستقیم';}toast('✓ Decision به‌روزرسانی شد')});}
