async function loadProviders(){const box=$('#v25ProviderList');if(!box)return;try{const d=await req('/integrations/catalog');state.aiProviders=d.items||d.providers||{};box.innerHTML=Object.entries(state.aiProviders).map(([k,v])=>`<div class="v25-provider"><b>${esc(v.name||k)}</b><span>${esc((v.capabilities||[]).join(' • '))}</span><em>${esc(v.status||'CONFIGURABLE')}</em></div>`).join('')}catch{box.innerHTML='<div class="v25-provider"><b>AI Providers</b><span>OpenAI • Gemini • Groq • GapGPT • Stability • Fal • Kling • BytePlus • PiAPI • MaxRouter</span><em>DEMO READY</em></div>'}}
function updateBellBadge(count){const b=$('#notificationBadge')||$('#bellBadge')||$('#badge');if(b){b.textContent=String(count||0);b.style.display=count>0?'inline-flex':'none';}const bell=$('#bell');if(bell)bell.setAttribute('aria-label',`اعلان‌ها${count>0?`؛ ${count} اعلان خوانده‌نشده`:''}`)}
async function loadNotifications({open=false}={}){
 const list=$('#notificationTimeline'); if(open)openOverlay('notificationOverlay'); if(!list)return;
 list.innerHTML='<div class="timelineItem"><b>در حال دریافت اعلان‌ها…</b><span>لطفاً کمی صبر کنید.</span></div>';
 try{const d=await req('/notifications');const items=Array.isArray(d.items)?d.items:[];updateBellBadge(Number(d.unread||items.filter(x=>!x.read_at).length));
   list.innerHTML=items.length?items.map(x=>`<button class="timelineItem ${x.read_at?'is-read':'is-unread'}" data-notification-id="${Number(x.id)||0}"><b>${esc(x.title)}</b><span>${esc(x.body||'')}</span><small>${esc(x.created_at||'')}</small></button>`).join(''):'<div class="timelineItem"><b>همه چیز آرام است</b><span>اعلان جدیدی وجود ندارد.</span></div>';
   $$('[data-notification-id]',list).forEach(item=>item.addEventListener('click',async()=>{const id=Number(item.dataset.notificationId||0);if(!id||item.classList.contains('is-read'))return;try{await req('/notifications/read',{method:'POST',body:JSON.stringify({id})});item.classList.remove('is-unread');item.classList.add('is-read');updateBellBadge(Math.max(0,Number($('#notificationBadge')?.textContent||0)-1))}catch(e){toast(e.message||'اعلان خوانده نشد','warn')}}));
 }catch(e){if(e.status===401){showLogin();list.innerHTML='<div class="timelineItem"><b>نیاز به ورود</b><span>برای مشاهده اعلان‌ها وارد حساب شوید.</span></div>'}else list.innerHTML='<div class="timelineItem"><b>خطا در دریافت اعلان‌ها</b><span>اتصال Backend را بررسی کنید.</span></div>'}
}
