async function restoreSession(){
 try{const d=await req('/auth/session');if(d.authenticated&&d.user){state.demo=false;showDash(d.user.display_name||d.user.username,'@'+d.user.username,false);updateBellBadge(0);await loadNotifications();return true}}catch{}
 return false;
}
async function setupV40(){
 const renderGrowth=(d)=>{
  if($('#growthScore'))$('#growthScore').textContent=Math.round(d.growth_score??0);
  const a=d.latest||{}; if($('#sigEng'))$('#sigEng').textContent=(a.engagement??0)+'%';
  if($('#sigReach'))$('#sigReach').textContent=Number(a.reach||0).toLocaleString('fa-IR');
  if($('#sigSave'))$('#sigSave').textContent=a.reach?((Number(a.saves||0)/Number(a.reach))*100).toFixed(2)+'%':'—';
  if($('#sigShare'))$('#sigShare').textContent=a.reach?((Number(a.shares||0)/Number(a.reach))*100).toFixed(2)+'%':'—';
  const recs=$('#growthRecommendations'); if(recs)recs.innerHTML=(d.recommendations||[]).slice(0,3).map(r=>`<div class="ip40-rec"><b>${esc(r.title)}</b><span>${esc(r.rationale||'')}</span><i>${Math.round(Number(r.score||0))}/100 • ${esc(r.priority||'')}</i></div>`).join('');
  const top=(d.recommendations||[])[0]; if(top){if($('#nextActionTitle'))$('#nextActionTitle').textContent=top.title;if($('#nextActionReason'))$('#nextActionReason').textContent=top.rationale||'';}
 };
 const load=async()=>{try{const d=await req('/growth/intelligence');renderGrowth(d)}catch{renderGrowth({growth_score:84,recommendations:[{title:'یک Reel اصیل با Hook قوی بسازید',rationale:'نسخه Demo بر اساس اصول سیگنال‌محور فعال است.',score:91,priority:'high'}]})}};
 $('#nextActionBtn')?.addEventListener('click',async()=>{try{const d=await req('/growth/next-action');$('#nextActionTitle').textContent=d.action.title;$('#nextActionReason').textContent=d.action.rationale||'';toast('✓ پیشنهاد بعدی به‌روزرسانی شد')}catch{toast('پیشنهاد Demo آماده است','warn')}});
 $('#reviewBtn')?.addEventListener('click',async()=>{const text=$('#reviewText')?.value.trim();if(!text){toast('متن محتوا را وارد کنید','warn');return}const box=$('#reviewResult');box.textContent='در حال بررسی…';try{const d=await req('/content/review',{method:'POST',body:JSON.stringify({text,type:$('#reviewType')?.value||'reel'})});const r=d.review;box.innerHTML=`<div class="scoreline"><span class="scorepill">امتیاز کل ${r.overall}</span><span class="scorepill">Hook ${r.hook}</span><span class="scorepill">Share ${r.share}</span><span class="scorepill">Save ${r.save}</span><span class="scorepill">Original ${r.originality}</span><span class="scorepill">Recommendation ${r.recommendation}</span><span class="scorepill">Risk ${esc(r.risk)}</span></div>${(r.findings||[]).map(x=>`<div class="finding">• ${esc(x)}</div>`).join('')||'<div>✓ نکته بحرانی پیدا نشد؛ قبل از انتشار نتیجه واقعی را اندازه‌گیری کنید.</div>'}`;toast('✓ بررسی محتوا انجام شد')}catch(e){box.textContent='حالت Demo: بررسی محلی انجام نشد؛ دوباره تلاش کنید.';toast('بررسی کامل نشد','warn')}});
 $('#dnaSave')?.addEventListener('click',async()=>{const payload={niche:$('#dnaNiche')?.value||'',audience:$('#dnaAudience')?.value||'',tone:$('#dnaTone')?.value||'',pillars:($('#dnaPillars')?.value||'').split(',').map(x=>x.trim()).filter(Boolean),confidence:85};try{await req('/growth/dna',{method:'POST',body:JSON.stringify(payload)});$('#dnaResult').textContent='✓ Profile DNA ذخیره شد و از این پس مبنای تصمیم‌های AI خواهد بود.';toast('✓ DNA پیج ذخیره شد')}catch{$('#dnaResult').textContent='حالت Demo: DNA در رابط آماده است؛ برای ذخیره واقعی Backend را نصب کنید.';toast('ذخیره Demo شد','warn')}});
 try{const d=await req('/growth/dna');const x=d.dna;if(x){$('#dnaNiche').value=x.niche||'';$('#dnaAudience').value=x.audience||'';$('#dnaTone').value=x.tone||'';$('#dnaPillars').value=Array.isArray(x.pillars)?x.pillars.join(', '):'';$('#dnaResult').textContent='✓ DNA فعلی بارگذاری شد.'}}catch{}
 load();
}
