 const attr=async()=>{try{const d=await req('/v42/attribution');$('#v42AttrSamples').textContent=d.samples??0;$('#v42Factors').innerHTML=(d.factors||[]).slice(0,4).map(x=>`<div class="ip42-factor"><strong>${Number(x.impact).toFixed(1)}</strong><b>${esc(x.factor)}</b><small>اثر میانگین بر اساس داده واقعی</small></div>`).join('')||'<div class="ip42-result">برای Attribution حداقل چند محتوای متصل و Insight لازم است.</div>';toast('✓ Attribution به‌روزرسانی شد')}catch(e){toast(e.message||'Attribution در دسترس نیست','warn')}};$('#v42AttrBtn')?.addEventListener('click',attr);
 try{const st=await req('/v42/sync-status');const x=st.items?.[0];if(x){$('#v42Synced').textContent=x.items_synced??'—';$('#v42Scanned').textContent=x.items_scanned??'—';$('#v42SyncStatus').textContent=`${x.status} • ${x.completed_at||x.started_at||''}`}}catch{};attr();
