 $('#v15Publish')?.addEventListener('click',async()=>{const mediaUrl=$('#v15MediaUrl')?.value.trim(),contentId=Number($('#v15ContentId')?.value||0);if(!mediaUrl){toast('Public media URL را وارد کنید','warn');return}try{await req('/instagram/publish',{method:'POST',body:JSON.stringify({content_id:contentId,type:'IMAGE',media_url:mediaUrl,caption:''})});$('#v15State').textContent='✓ انتشار با Instagram انجام شد.';toast('✓ محتوا منتشر شد')}catch(e){$('#v15State').textContent=state.demo?'✓ Demo: درخواست انتشار شبیه‌سازی شد.':(e.message||'انتشار انجام نشد.');toast(state.demo?'✓ Demo Publish آماده شد':'انتشار انجام نشد','warn')}});
 $('#v16Launch')?.addEventListener('click',()=>openOverlay('v16Overlay'));
